<?php require __DIR__.'/../config.php';$slug=trim($_GET['slug']??'');$st=db()->prepare("SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status='published' LIMIT 1");$st->execute([$slug]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Post not found');}$title=$p['meta_title']?:$p['title'];$desc=$p['meta_description']?:$p['excerpt'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($desc)?>"><link rel="stylesheet" href="../assets/style.css"><style>.article{max-width:900px;margin:auto;padding-top:150px}.article img{max-width:100%;border-radius:18px}.article-body{font-size:18px;line-height:1.9;color:#c7c7cc}.article-body h2,.article-body h3{color:#fff}.article-body a{color:#ff653d}</style></head><body><header class="nav"><a class="logo" href="../">SK<span>.</span></a><nav><a href="../#work">Work</a><a href="../#skills">Skills</a><a href="./">Blog</a><a href="../#about">About</a><a href="../#contact">Contact</a></nav></header><main class="article"><span class="label"><?=e($p['category_name']?:'ARTICLE')?></span><h1 style="font-size:clamp(48px,7vw,90px);letter-spacing:-5px;line-height:.95"><?=e($p['title'])?></h1><p class="muted"><?=e($p['published_at']?:$p['created_at'])?></p><?php if($p['image_url']):?><img src="../<?=e($p['image_url'])?>" alt="<?=e($p['title'])?>"><?php endif;?><div class="article-body"><?= $p['content'] ?></div><p style="margin:60px 0"><a class="btn ghost" href="./">← Back to blog</a></p></main></body></html>
